function enhanceSchemeEditor(){const form=document.querySelector('#schemeForm'),table=form?.querySelector('.scheme-table');if(!table)return;const holder=table.parentElement,layout=document.createElement('div');layout.className='scheme-editor-layout';const cards=document.createElement('div');cards.className='scheme-node-cards';const inputLabel=container=>{container.querySelectorAll('input:not([type=hidden]):not([type=checkbox])').forEach(input=>{const label=input.getAttribute('aria-label')||input.previousElementSibling?.textContent||'时限';input.setAttribute('aria-label',label);const tag=document.createElement('label');tag.className='scheme-input-caption';tag.textContent=label;input.before(tag)})};[...table.tBodies[0].rows].filter(tr=>tr.cells.length===5).forEach((tr,i)=>{const r=edit.rules[i],cells=tr.cells,node=document.createElement('section');node.className='scheme-node-card';node.id='scheme-node-'+r.id;const head=document.createElement('header');head.innerHTML='<div><span class="scheme-node-index">'+(i+1)+'</span><b>'+labels[r.id]+'</b></div>';const enabled=document.createElement('label');enabled.className='scheme-node-enabled';enabled.append(cells[0].querySelector('input'),document.createTextNode('启用监控'));head.append(enabled);node.append(head);const timing=document.createElement('div');timing.className='scheme-node-timing';while(cells[2].firstChild)timing.append(cells[2].firstChild);const select=timing.querySelector('[name=timingMode'+i+']');if(select&&r.id!=='sign'){select.hidden=true;const modes=document.createElement('div');modes.className='scheme-mode-options';for(const [value,title,desc] of [['hours','固定小时','到货前预留明确的小时数'],['ratio','时间比例','随本单可用履约时间伸缩']]){const b=document.createElement('button');b.type='button';b.className=select.value===value?'selected':'';b.setAttribute('aria-pressed',String(select.value===value));b.innerHTML='<b>'+title+'</b><span>'+desc+'</span>';b.onclick=()=>{const top=window.scrollY;select.value=value;captureForm();draw();window.scrollTo(0,top);document.querySelector('#scheme-node-'+r.id+' .scheme-mode-options .selected')?.focus({preventScroll:true})};modes.append(b)}timing.prepend(modes)}inputLabel(timing);node.append(timing);const summary=document.createElement('p');summary.className='scheme-rule-sentence';summary.dataset.nodeIndex=i;node.append(summary);const advanced=document.createElement('details');advanced.className='scheme-node-advanced';const title=document.createElement('summary');title.textContent='预警与责任设置';advanced.append(title);const grid=document.createElement('div');grid.className='scheme-advanced-grid';const warn=document.createElement('div');warn.innerHTML='<h4>预警</h4>';while(cells[3].firstChild)warn.append(cells[3].firstChild);inputLabel(warn);const owner=document.createElement('label');owner.innerHTML='<h4>责任用户</h4>';owner.append(cells[4].querySelector('select'));grid.append(warn,owner);advanced.append(grid);node.append(advanced);cards.append(node)});const preview=document.createElement('aside');preview.className='scheme-live-preview';preview.innerHTML='<h3>本方案时间轴预览</h3><p>边配置边查看结果，试算不修改订单。</p><label>订单提交<input type="datetime-local" id="schemePreviewStart" value="2026-11-05T10:00"></label><label>要求到货<input type="datetime-local" id="schemePreviewEnd" value="2026-11-07T10:00"></label><div class="scheme-preview-presets"><button type="button" data-days="2">2天订单</button><button type="button" data-days="5">5天订单</button></div><div id="schemeLiveResult" aria-live="polite"></div>';layout.append(cards,preview);holder.replaceWith(layout);preview.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{const date=new Date(document.querySelector('#schemePreviewStart').value);date.setDate(date.getDate()+Number(b.dataset.days));document.querySelector('#schemePreviewEnd').value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);updateSchemeLive()});form.addEventListener('input',updateSchemeLive);form.addEventListener('change',updateSchemeLive);updateSchemeLive()}
function updateSchemeLive(){const form=document.querySelector('#schemeForm');if(!form)return;const d=form.elements,start=new Date(d.schemePreviewStart.value).getTime(),end=new Date(d.schemePreviewEnd.value).getTime(),hours=(end-start)/3600000,out=document.querySelector('#schemeLiveResult');if(isArrivalScene(edit)&&(!Number.isFinite(hours)||hours<=0)){out.textContent='请设置晚于提交时间的到货时间';return}let results=isArrivalScene(edit)?'<p class="scheme-total-hours">本单可用时间 <b>'+hours+' 小时</b></p>':'<p>未指定到货时间，按接单库存方式及实际事件正向试算。</p>',previous=start;const deadlines={};edit.rules.forEach((r,i)=>{const mode=d['timingMode'+i]?.value||'hours',reverse=isArrivalScene(edit)&&reverseNode(r.id),lead=reverse?(mode==='ratio'?hours*Number(d['ratio'+i].value)/100:Number(d['lead'+i].value)):0;const sentence=form.querySelector('[data-node-index="'+i+'"]');if(sentence)sentence.textContent=reverse?(r.id==='sign'?'签收截止就是客户要求到货时间':mode==='ratio'?'到货前预留总时长的 '+d['ratio'+i].value+'%，本例为 '+Number(lead.toFixed(2))+' 小时。':'到货前至少 '+lead+' 小时完成'+labels[r.id]+'。'):'从实际业务事件起，按节点时限正向计时。';if(!d['on'+i].checked)return;if(r.id==='finance'){const times=[...form.querySelectorAll('[name=financeReminderTime]')].map(x=>x.value).filter(Boolean);results+='<div class="scheme-preview-node"><b>财务审核提醒</b><strong>每日 '+(times.length?times.join('、'):'请设置时间点')+'</strong><span>到点检查待审核订单，不计节点超时</span></div>';return}const stock=document.querySelector('#scenarioStock')?.value||'stock';const duration=r.id==='ship'&&!isArrivalScene(edit)?Number(stock==='noStock'?defaults.product.noStock:defaults.product.stock):Number(d['hours'+i].value);const at=reverse?end-lead*3600000:((r.id==='finance'||r.id==='accept')?start:previous)+duration*3600000;previous=at;deadlines[r.id]=at;const conflict=reverse&&(at<start||lead<Number(d['minimum'+i].value));results+='<div class="scheme-preview-node '+(conflict?'conflict':'')+'"><b>'+labels[r.id]+'</b><strong>'+new Date(at).toLocaleString('zh-CN',{hour12:false})+'</strong><span>'+(conflict?(at<start?'交期冲突：截止早于下单':'交期冲突：不足最少需要时间'):reverse?'到货前预留 '+Number(lead.toFixed(2))+' 小时':'事件起算的预计时间')+'</span></div>'});for(const [a,b] of [['ship','pickup'],['pickup','sign']])if(deadlines[a]>deadlines[b])results+='<p class="scheme-preview-error">顺序冲突：'+labels[a]+'截止晚于'+labels[b]+'</p>';out.innerHTML=results}


const cardEditorBase=enhanceSchemeEditor;
enhanceSchemeEditor=function(){cardEditorBase();const layout=document.querySelector('.scheme-editor-layout');if(!layout)return;const form=document.querySelector('#schemeForm'),d=form.elements,preview=layout.querySelector('.scheme-live-preview'),cards=[...layout.querySelectorAll('.scheme-node-card')];const table=document.createElement('table');table.className='scheme-table scheme-config-matrix';table.innerHTML='<thead><tr><th>监控</th><th>履约节点</th><th>计时基准</th><th>配置方式</th><th>时限 / 预留值</th><th>最少需要时间</th><th>截止前提醒</th><th>责任用户</th><th>本单试算截止</th></tr></thead><tbody></tbody>';cards.forEach((card,i)=>{const r=edit.rules[i],reverse=isArrivalScene(edit)&&reverseNode(r.id),tr=table.tBodies[0].insertRow();for(let c=0;c<9;c++)tr.insertCell();tr.cells[0].append(d['on'+i]);tr.cells[1].innerHTML='<b>'+labels[r.id]+'</b>';tr.cells[2].textContent=reverse?'要求到货前倒排':'实际事件后起算';const mode=d['timingMode'+i];if(mode){mode.hidden=false;tr.cells[3].append(mode)}else tr.cells[3].textContent='固定小时';const value=tr.cells[4];if(reverse){for(const name of ['lead','ratio']){const input=d[name+i],wrap=document.createElement('div');wrap.hidden=(mode.value==='ratio')!==(name==='ratio');wrap.append(input,document.createTextNode(name==='ratio'?' %':' 小时'));value.append(wrap)}tr.cells[5].append(d['minimum'+i],document.createTextNode(' 小时'));if(false){const group=document.createElement('div');group.className='scheme-forward-note';group.append(document.createTextNode('非系统客户：'),d['hours'+i],document.createTextNode(r.id==='ship'?'读取有货 / 无货商品时效':' 小时'));value.append(group)}else value.append(d['hours'+i])}else{value.append(d['hours'+i]);value.append(document.createTextNode(r.id==='ship'?'读取商品时效':' 小时'));tr.cells[5].textContent='—'}const warning=tr.cells[6];const warningHours=d['warningHours'+i];if(warningHours){warning.append(document.createTextNode('截止前 '),warningHours,document.createTextNode(' 小时'));const forwardWarn=d['warn'+i];if(false){const small=document.createElement('div');small.className='scheme-forward-note';small.append(document.createTextNode('非系统客户 '),forwardWarn,document.createTextNode('%'));warning.append(small)}else warning.append(forwardWarn)}else warning.append(d['warn'+i],document.createTextNode(' %'));tr.cells[7].append(d['owner'+i]);tr.cells[8].className='scheme-row-result';tr.cells[8].dataset.resultIndex=i;});const scroll=document.createElement('div');scroll.className='scheme-matrix-scroll';scroll.append(table);const panel=document.createElement('section');panel.className='scheme-inline-preview';preview.querySelector('h3').textContent='试算条件';panel.append(...preview.childNodes);layout.replaceWith(panel,scroll);updateSchemeLive()};
const matrixLiveBase=updateSchemeLive;
updateSchemeLive=function(){matrixLiveBase();const results=[...document.querySelectorAll('#schemeLiveResult .scheme-preview-node')];let index=0;edit.rules.forEach((r,i)=>{const cell=document.querySelector('[data-result-index="'+i+'"]');if(!cell)return;if(!document.querySelector('#schemeForm').elements['on'+i].checked){cell.textContent='未启用';return}const node=results[index++];cell.innerHTML=node?node.innerHTML.replace(/<b>.*?<\/b>/,''):'请检查试算时间';cell.classList.toggle('conflict',node?.classList.contains('conflict')||false)});};


const labelledMatrixBase=enhanceSchemeEditor;
enhanceSchemeEditor=function(){labelledMatrixBase();const f=document.querySelector('#schemeForm');if(!f)return;const d=f.elements;document.querySelectorAll('.scheme-config-matrix tbody tr').forEach((tr,i)=>{const r=edit.rules[i],reverse=isArrivalScene(edit)&&reverseNode(r.id);const group=(label,controls,unit,extra)=>{const el=document.createElement('div');el.className='scheme-customer-line';const tag=document.createElement('span');tag.className='scheme-customer-label';tag.textContent=label;const value=document.createElement('div');value.className='scheme-customer-value';controls.forEach(c=>{if(c)value.append(c)});if(unit){const u=document.createElement('span');u.className='scheme-field-unit';u.textContent=unit;value.append(u)}if(extra){const text=document.createElement('span');text.textContent=extra;value.append(text)}el.append(tag,value);return el};const value=tr.cells[4],warning=tr.cells[6];const hours=d['hours'+i],warn=d['warn'+i],min=d['minimum'+i];const lead=d['lead'+i],ratio=d['ratio'+i],warningHours=d['warningHours'+i];value.replaceChildren();warning.replaceChildren();if(reverse){const mode=d['timingMode'+i].value,active=mode==='ratio'?ratio:lead,inactive=mode==='ratio'?lead:ratio;const hidden=document.createElement('div');hidden.hidden=true;hidden.append(inactive);value.append(group('系统客户',[active],mode==='ratio'?'%':'小时'),hidden);warning.append(group('系统客户',[warningHours],'小时','截止前'));if(false){value.append(group('非系统客户',[hours],r.id==='ship'?'':'小时',r.id==='ship'?'读取商品时效':''));warning.append(group('非系统客户',[warn],'%','已用时'))}else{value.append(hours);warning.append(warn)}if(min){tr.cells[5].replaceChildren(group('系统客户',[min],'小时'))}}else{const label=edit.type==='非系统客户'?'非系统客户':edit.type==='系统客户'?'系统客户':'全部客户';value.append(group(label,[hours],r.id==='ship'?'':'小时',r.id==='ship'?'读取商品时效':''));warning.append(group(label,[warn],'%','已用时'))}})};


const helpEditorBase=enhanceSchemeEditor;
enhanceSchemeEditor=function(){helpEditorBase();const table=document.querySelector('.scheme-config-matrix');if(!table)return;const tips={5:['最少需要时间','从本节点完成到客户要求到货，后续环节至少需要的小时数。例如运输至少需要24小时，就填24；比例计算只留下10小时时提示交期风险。该值仅校验，不自动修改截止时间；填0表示不额外校验。'],6:['截止前提醒','履约过程中，距离本节点截止时间还有多少小时开始提醒。例如填4，表示截止前4小时提醒。非系统客户显示的百分比仍表示已用时达到该比例时提醒。']};Object.entries(tips).forEach(([i,[name,text]])=>{const th=table.tHead.rows[0].cells[Number(i)];th.replaceChildren(document.createTextNode(name+' '));const wrap=document.createElement('span');wrap.className='scheme-help';const button=document.createElement('button');button.type='button';button.className='scheme-help-trigger';button.setAttribute('aria-label',name+'说明');const tip=document.createElement('span');tip.className='scheme-help-tooltip';tip.id='scheme-tip-'+i;tip.setAttribute('role','tooltip');tip.textContent=text;button.setAttribute('aria-describedby',tip.id);button.textContent='?';button.onclick=()=>wrap.classList.toggle('is-open');button.onkeydown=e=>{if(e.key==='Escape')wrap.classList.remove('is-open')};wrap.append(button,tip);th.append(wrap)})};


