const userCustomerEditorBase=enhanceSchemeEditor;
enhanceSchemeEditor=function(){userCustomerEditorBase();const form=document.querySelector('#schemeForm'),scope=document.querySelector('#targetScope'),targets=document.querySelector('#schemeTargets');if(!form||!scope)return;const label=scope.closest('label');const caption=label.firstChild;if(caption?.nodeType===3)caption.textContent='选择客户';scope.hidden=true;scope.value='specific';targets.hidden=false;targets.classList.add('scheme-customer-picker');label.append(targets);const search=document.createElement('input');search.type='search';search.placeholder='搜索客户名称';search.setAttribute('aria-label','搜索适用客户');search.className='scheme-customer-search';targets.before(search);const info=document.createElement('p');info.className='scheme-selection-count';targets.after(info);const update=()=>{info.textContent='已选择 '+targets.querySelectorAll('input:checked').length+' 个客户（可多选）'};targets.querySelectorAll('label').forEach(el=>el.classList.add('scheme-customer-option'));search.oninput=()=>targets.querySelectorAll('label').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(search.value.trim().toLowerCase()));targets.addEventListener('change',update);if(edit.targets.some(t=>!customers().includes(t))){info.insertAdjacentHTML('afterend','<p class="scheme-error">原方案使用集团或范围匹配，请重新选择具体客户后保存。</p>')}update();const note=label.parentElement.nextElementSibling?.nextElementSibling;if(note?.classList.contains('scheme-note'))note.textContent='按所选具体客户匹配方案；客户类型用于决定计时规则。新配置不影响历史订单快照。';edit.rules.forEach((r,i)=>{const select=form.elements['owner'+i];select.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=r.ownerUserId?'请选择用户':'请选择用户（原角色需指定人员）';select.append(placeholder);for(const u of schemeUsers){const option=document.createElement('option');option.value=u.id;option.textContent=u.name+' · '+u.dept;select.append(option)}select.value=r.ownerUserId||'';select.setAttribute('aria-label',labels[r.id]+'责任用户');select.required=form.elements['on'+i].checked;form.elements['on'+i].addEventListener('change',()=>{select.required=form.elements['on'+i].checked})});};


function openSchemePicker({title,items,multiple,selected,onApply}){document.querySelector('#schemePickerDialog')?.remove();const draft=new Set(selected),dialog=document.createElement('dialog');dialog.id='schemePickerDialog';dialog.className='scheme-picker-dialog';dialog.setAttribute('aria-labelledby','schemePickerTitle');dialog.innerHTML='<header class="scheme-picker-head"><div><h2 id="schemePickerTitle">'+title+'</h2><p>'+(multiple?'可选择多个客户，确认后回填到当前方案':'选择具体责任用户，确认后回填当前节点')+'</p></div><button type="button" class="btn" data-close aria-label="关闭选择弹窗">关闭</button></header><div class="scheme-picker-tools"><input type="search" aria-label="搜索选择项" placeholder="输入名称或编号搜索"><select aria-label="筛选分类"><option value="">全部分类</option></select></div><div class="scheme-picker-body"><div><div class="scheme-picker-list-title"><b>可选列表</b><span id="pickerResults"></span></div><div class="scheme-picker-options"></div></div><section class="scheme-picker-selection"><div class="scheme-picker-list-title"><b>已选项目</b><span id="pickerSelectedCount"></span></div><div class="scheme-picker-selected-items"></div></section></div><footer class="scheme-picker-foot"><span id="pickerCount" role="status"></span><div><button type="button" class="btn" data-close>取消</button><button type="button" class="btn primary" id="pickerApply">确认选择</button></div></footer>';document.body.append(dialog);const search=dialog.querySelector('input'),category=dialog.querySelector('select');[...new Set(items.map(i=>i.group))].forEach(group=>{const o=document.createElement('option');o.value=group;o.textContent=group;category.append(o)});const refresh=()=>{const shown=items.filter(item=>(!category.value||item.group===category.value)&&[item.name,item.id].join(' ').toLowerCase().includes(search.value.trim().toLowerCase()));dialog.querySelector('#pickerResults').textContent=shown.length+' 项';dialog.querySelector('#pickerSelectedCount').textContent=draft.size+' 项';dialog.querySelector('#pickerCount').textContent='已选择 '+draft.size+' 项';const list=dialog.querySelector('.scheme-picker-options');list.replaceChildren();for(const item of shown){const label=document.createElement('label');label.className='scheme-picker-option';const input=document.createElement('input');input.type=multiple?'checkbox':'radio';input.name='pickerChoice';input.value=item.id;input.checked=draft.has(item.id);const text=document.createElement('div');const name=document.createElement('b');name.textContent=item.name;const sub=document.createElement('small');sub.textContent=item.group; text.append(name,sub);label.append(input,text);input.onchange=()=>{if(!multiple)draft.clear();if(input.checked)draft.add(item.id);else draft.delete(item.id);refresh()};list.append(label)}if(!shown.length)list.innerHTML='<div class="scheme-picker-empty">没有匹配结果，请调整搜索或分类。</div>';const chosen=dialog.querySelector('.scheme-picker-selected-items');chosen.replaceChildren();for(const id of draft){const item=items.find(i=>i.id===id);if(!item)continue;const row=document.createElement('div');row.className='scheme-picker-chosen';const text=document.createElement('span');text.textContent=item.name;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','移除 '+item.name);remove.onclick=()=>{draft.delete(id);refresh()};row.append(text,remove);chosen.append(row)}if(!draft.size)chosen.innerHTML='<p class="scheme-picker-empty">尚未选择</p>'};search.oninput=refresh;category.onchange=refresh;dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('#pickerApply').onclick=()=>{onApply([...draft]);dialog.close()};refresh();dialog.showModal();search.focus()}
